export const FAVICON_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 138 140" fill="currentColor" fill-rule="evenodd"><path d="' + FAVICON_PATH_D + '"/></svg>';

/** Content-hashed path of LOGO_SVG, served with a long cache by the app. */
export const LOGO_ASSET_PATH = `/assets/logo.${createHash('sha256').update(LOGO_SVG).digest('hex').slice(0, 10)}.svg`;

/**
 * The traced logo path is ~14 KB, so pages reference the cached SVG as a CSS mask
 * instead of inlining it; the mask is painted with currentColor and follows the theme.
 */
export function renderLogo(options: { height?: number; className?: string } = {}): string {
  const height = options.height ?? 22;
  const className = options.className ?? 'brand-logo-svg';
  const mask = `url(${LOGO_ASSET_PATH}) no-repeat center/contain`;
  return '<span class="' + className + '" role="img" aria-label="openradar" style="height:' + height + 'px;aspect-ratio:794/140;display:inline-block;vertical-align:middle;background-color:currentColor;-webkit-mask:' + mask + ';mask:' + mask + '"></span>';
}

export function renderFavicon(options: { height?: number; className?: string } = {}): string {
  const height = options.height ?? 22;
  const className = options.className ?? 'brand-favicon-svg';
  return '<svg class="' + className + '" viewBox="0 0 138 140" fill="currentColor" fill-rule="evenodd" style="height:' + height + 'px;width:auto;display:inline-block;vertical-align:middle" role="img" aria-label="openradar"><path d="' + FAVICON_PATH_D + '"/></svg>';
}
